#!/usr/bin/env node
/**
 * CI + local gate for the "tracked entry references missing dist assets"
 * production failure mode: GET /marketplace/ returned 200 HTML while its
 * ./dist/assets/*.js|css returned 404 = blank page.
 *
 * The PRODUCTION entry is the tracked marketplace/index.html: express.static
 * serves it as the directory index of /marketplace/. dist/ is gitignored and
 * regenerated by the deploy build, so a committed entry that references asset
 * hashes the next build will not emit is an outage waiting to ship.
 *
 * Usage:
 *   node scripts/verify-entry-assets.mjs
 *   node scripts/verify-entry-assets.mjs --entry <path> --root <dir>
 *
 * Exit codes: 0 = every referenced local asset exists; 1 = missing/unreadable.
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { assertReferencedAssetsExist } from "./postbuild.js";

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const pkgRoot = path.dirname(scriptDir);

const args = process.argv.slice(2);
const flag = (name) => {
  const i = args.indexOf("--" + name);
  return i !== -1 && i + 1 < args.length ? args[i + 1] : null;
};

const entry = path.resolve(flag("entry") || path.join(pkgRoot, "index.html"));
const root = path.resolve(flag("root") || pkgRoot);

let html;
try {
  html = fs.readFileSync(entry, "utf8");
} catch (err) {
  console.error("verify-entry-assets: cannot read entry " + entry + " (" + err.message + ")");
  console.error("verify-entry-assets=FAIL");
  process.exit(1);
}

try {
  assertReferencedAssetsExist(html, root, path.relative(process.cwd(), entry) || entry);
} catch (err) {
  console.error(String(err.message || err));
  console.error("verify-entry-assets=FAIL");
  process.exit(1);
}
console.log("verify-entry-assets=PASS (entry: " + entry + ")");
